CREATE TABLE IF NOT EXISTS reward_settings(guild INTEGER PRIMARY KEY,channel INTEGER NOT NULL DEFAULT 0,cursor INTEGER NOT NULL DEFAULT 0,epoch INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS reward_spins(id INTEGER PRIMARY KEY AUTOINCREMENT,guild INTEGER NOT NULL,user INTEGER NOT NULL,reference TEXT NOT NULL,created INTEGER NOT NULL,result TEXT NOT NULL,UNIQUE(guild,reference));
CREATE INDEX IF NOT EXISTS reward_spins_user ON reward_spins(guild,user,id);
CREATE TABLE IF NOT EXISTS reward_rerolls(guild INTEGER NOT NULL,user INTEGER NOT NULL,amount INTEGER NOT NULL CHECK(amount>=0),PRIMARY KEY(guild,user));
CREATE TABLE IF NOT EXISTS reward_cycles(guild INTEGER NOT NULL,user INTEGER NOT NULL,cycle INTEGER NOT NULL,day INTEGER NOT NULL,permit_day INTEGER NOT NULL,last_date TEXT NOT NULL,PRIMARY KEY(guild,user));
CREATE TABLE IF NOT EXISTS reward_days(id INTEGER PRIMARY KEY AUTOINCREMENT,guild INTEGER NOT NULL,user INTEGER NOT NULL,date TEXT NOT NULL,report INTEGER NOT NULL,cycle INTEGER NOT NULL,day INTEGER NOT NULL,result TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'pending',error TEXT NOT NULL DEFAULT '',created INTEGER NOT NULL,UNIQUE(guild,user,date));
CREATE INDEX IF NOT EXISTS reward_pending ON reward_days(state,id);
CREATE TABLE IF NOT EXISTS reward_seen(guild INTEGER NOT NULL,report INTEGER NOT NULL,user INTEGER NOT NULL,PRIMARY KEY(guild,report,user));
CREATE TABLE IF NOT EXISTS reward_audit(id INTEGER PRIMARY KEY AUTOINCREMENT,guild INTEGER NOT NULL,user INTEGER NOT NULL,action TEXT NOT NULL,detail TEXT NOT NULL,created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS reward_audit_guild ON reward_audit(guild,id);
CREATE TRIGGER IF NOT EXISTS reward_audit_immutable_update BEFORE UPDATE ON reward_audit BEGIN SELECT RAISE(ABORT,'audit inmutable'); END;
CREATE TRIGGER IF NOT EXISTS reward_audit_immutable_delete BEFORE DELETE ON reward_audit BEGIN SELECT RAISE(ABORT,'audit inmutable'); END;
CREATE TABLE IF NOT EXISTS reward_reset_tokens(token TEXT PRIMARY KEY,guild INTEGER NOT NULL,owner INTEGER NOT NULL,expires INTEGER NOT NULL,fingerprint TEXT NOT NULL,used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS reward_counters(name TEXT PRIMARY KEY,value INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS reward_mission_cursor ON mission_audit(guild,id,action);
